import{_ as d,a0 as l,w as i,s as n,ao as p,I as r,x as s,a1 as o,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"Linus Torvalds吐槽Fedora項目，連呼數個Stupid！ | LCTT x X-CMD","titleTemplate":false,"description":"Linus Torvalds吐槽Fedora項目，連呼數個Stupid！ | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linus Torvalds吐槽Fedora項目，連呼數個Stupid！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linus Torvalds吐槽Fedora項目，連呼數個Stupid！ | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Linus Torvalds Smashes the Fedora Project, Calls Them Stupid","title":"Linus Torvalds吐槽Fedora項目，連呼數個Stupid！","tag":"201310","desc":""},"relativePath":"201310/Linus Torvalds Smashes the Fedora Project, Calls Them Stupid.md","filePath":"[post].md"}'),u={name:"201310/Linus Torvalds Smashes the Fedora Project, Calls Them Stupid.md"};function T(m,t,L,f,S,v){const e=l("Link");return i(),n("div",null,[t[14]||(t[14]=p('<h1 id="linus-torvalds吐槽fedora項目-連呼數個stupid" tabindex="-1">Linus Torvalds吐槽Fedora項目，連呼數個Stupid！ <a class="header-anchor" href="#linus-torvalds吐槽fedora項目-連呼數個stupid" aria-label="Permalink to “Linus Torvalds吐槽Fedora項目，連呼數個Stupid！”">​</a></h1><p><strong>Linus Torvalds 在Google+上發佈了一個非常簡單直接的關於Fedora的信息，緊接着就引發了一系列譴責和各式吐槽。</strong></p><p><img src="http://i1-news.softpedia-static.com/images/news2/Linus-Torvalds-Smashes-the-Fedora-Project-Calls-Them-Stupid-393127-2.jpg" alt=""></p><p>Linux之父發佈的是一個非常簡單的問題：Fedora開發者為何不更新發行版鏡像，加入最新的內核與軟件包？</p><p>Linus Torvalds説：“為什麼你們從來不更新安裝鏡像呢？難道有什麼難言之隱？現在Fedora19的安裝鏡像還在使用古董級的3.9版內核。這意味着雖然它們能安裝在大多數機器上，但是卻無法支持像新型筆記本上的無線ID等等這樣的功能，所以遷就於通用性完全是不必要的痛苦”。</p><p>問題是這樣的，如果你有一台新筆記本，卻配了一個老內核，你可能無法完全發揮筆記本的功能，特別是當老內核無法識別無線模組的時候。</p><p>也許更新至新內核是個解決辦法，但是為了獲取新內核，你得訪問互聯網，但這是不可能的，因為剛不是説了你的老內核無法識別無線硬件模組嗎？於是，如此反覆，一個悲劇的怪圈誕生了。當然，如果剛好你的名字叫Linus Torvalds，這個問題就很好解決了，因為你知道如何不通過互聯網而是靠自己來編譯內核。</p><p>消息發佈沒多久，一些紅帽開發者開始試圖解釋説，他們負擔不起僱人測試的開銷，因此無法發佈有可能無法工作的鏡像。</p><p>Torvalds説，“現在你們説‘我們沒法測試鏡像’，要我説你們這是[敷衍]，因為現有的舊鏡像本來就有問題，所以號稱新的鏡像有可能出問題，完全是很愚蠢(stupid)的！難道不是嗎？”説完這些，Linus還不停嘴，</p><p>他繼續説道：“因此，你們所有的説辭都是愚蠢(stupid)的敷衍！你們要做的就是更新Fedora19到Fedora19.x，告知人們它將‘持續更新’，然後停止為本就有問題的鏡像尋找愚蠢(stupid)的藉口，因為你們壓根就沒打算測試新鏡像是否有問題。”</p>',10)),r("p",null,[t[1]||(t[1]=s("爭論雙方仍在持續發佈新的消息，看起來不遠的將來我們就能夠看到Fedora的鏡像更新了。能翻牆的小夥伴們可以到Linus Torvalds的",-1)),o(e,{href:"https://plus.google.com/102150693225130002912/posts/GqUgcYcfQuV"},{default:a(()=>[...t[0]||(t[0]=[s("Google+頁面",-1)])]),_:1}),t[2]||(t[2]=s("去圍觀一下湊個熱鬧。",-1))]),t[15]||(t[15]=r("hr",null,null,-1)),r("p",null,[t[4]||(t[4]=s("via: ",-1)),o(e,{href:"http://news.softpedia.com/news/Linus-Torvalds-Smashes-the-Fedora-Project-Calls-Them-Stupid-393127.shtml"},{default:a(()=>[...t[3]||(t[3]=[s("http://news.softpedia.com/news/Linus-Torvalds-Smashes-the-Fedora-Project-Calls-Them-Stupid-393127.shtml",-1)])]),_:1})]),r("p",null,[t[7]||(t[7]=s("譯者：",-1)),o(e,{href:"https://blog.csdn.net/tinyeyeser"},{default:a(()=>[...t[5]||(t[5]=[s("Mr小眼兒",-1)])]),_:1}),t[8]||(t[8]=s(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[6]||(t[6]=[s("wxy",-1)])]),_:1})]),r("p",null,[t[11]||(t[11]=s("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[9]||(t[9]=[s("LCTT",-1)])]),_:1}),t[12]||(t[12]=s(" 原創翻譯，",-1)),o(e,{href:"http://linux.cn/"},{default:a(()=>[...t[10]||(t[10]=[s("Linux中國",-1)])]),_:1}),t[13]||(t[13]=s(" 榮譽推出",-1))])])}const g=d(u,[["render",T]]);export{h as __pageData,g as default};
